    result = []
    for s in a:
        length = len(s)
        count = 0
        for l in range(length):
            for r in range(l, length):
                substr = s[l:r+1]
                if substr_counts[substr] >= k:
                    count += 1
        result.append(count)

    print(' '.join(map(str, result)))

